SELECT COUNT(*) AS empty_versions FROM poem_versions WHERE length(trim(COALESCE(content, ''), char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279))) = 0;
SELECT COUNT(*) AS empty_poems FROM poems p WHERE NOT EXISTS (SELECT 1 FROM poem_versions pv WHERE pv.poem_id = p.id AND NOT (length(trim(COALESCE(pv.content, ''), char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279))) = 0));
SELECT COUNT(*) AS archived_empty_versions FROM deleted_poems, json_each(CASE WHEN json_valid(versions_json) THEN versions_json ELSE '[]' END) WHERE length(trim(COALESCE(json_extract(value, '$.content'), ''), char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279))) = 0;
SELECT COUNT(*) AS populated_versions FROM poem_versions WHERE NOT (length(trim(COALESCE(content, ''), char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279))) = 0);
